.fm-meter[data-level="1"] i:nth-child(-n+1), .fm-meter[data-level="2"] i:nth-child(-n+2),
.fm-meter[data-level="3"] i:nth-child(-n+3), .fm-meter[data-level="4"] i:nth-child(-n+4) { background: var(--accent); }
.fm-check { display: flex; gap: 0.5rem; align-items: center; font-size: 0.9rem; }
